<?php
$member = isset($_GET['member']) ? (string) $_GET['member'] : 'TW-MEMBER-founder';
if (!preg_match('/^TW-MEMBER-[A-Za-z0-9_-]+$/',$member)) { http_response_code(400); exit('Invalid member ID.'); }
$file = __DIR__ . '/profiles-public/' . $member . '.json';
if (!is_file($file)) { http_response_code(404); exit('Profile not found.'); }
$profile = json_decode((string)file_get_contents($file), true);
if (!is_array($profile) || ($profile['profile_visibility'] ?? 'private') !== 'public') { http_response_code(404); exit('Profile not found.'); }
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
?>
