<section class="section"><div class="container"><div class="eyebrow">Theology positions</div><h2>What this member currently holds</h2><?php foreach (($profile['positions'] ?? []) as $p): ?><article class="panel" style="margin:1rem 0"><div class="status"><?= e($p['topic']) ?> · <?= e($p['stance']) ?></div><h3><?= e($p['p']) ?></h3><?php if (!empty($p['not_p'])): ?><p><strong>Contradiction:</strong> <?= e($p['not_p']) ?></p><?php endif; ?><p><?= e($p['member_explanation'] ?? '') ?></p><h4>Evidence on record</h4><ul class="clean"><?php foreach (($p['evidence'] ?? []) as $ev): ?><li><strong><?= e($ev['position'] ?? '') ?></strong> — <?= e($ev['citation'] ?? '') ?><?= !empty($ev['note']) ? ': '.e($ev['note']) : '' ?></li><?php endforeach; ?></ul><?php if (!empty($p['linked_truth_trials'])): ?><p><strong>Linked Truth Trials:</strong> <?php foreach ($p['linked_truth_trials'] as $trial): ?><a href="/trust-worthy/case.php?id=<?= rawurlencode($trial) ?>"><?= e($trial) ?></a> <?php endforeach; ?></p><?php endif; ?><div class="actions"><a class="button" href="/trust-worthy/member-challenge.php?member=<?= rawurlencode($profile['member_id']) ?>&position=<?= rawurlencode($p['position_id']) ?>">Challenge This Belief</a></div><h4>Revision ledger</h4><div class="history"><?php foreach (($p['revision_history'] ?? []) as $h): ?><div class="history-item"><strong><?= e($h['date'] ?? '') ?></strong> · <?= e($h['from'] ?? '') ?> → <?= e($h['to'] ?? '') ?><br><span class="muted"><?= e($h['reason'] ?? '') ?></span></div><?php endforeach; ?></div></article><?php endforeach; ?></div></section>
